using System.Threading;
using System.Threading.Tasks;

public record UserDto(string Id, string Email);

public interface IUserRepository
{
    Task<UserDto?> GetByIdAsync(string id, CancellationToken cancellationToken);
}

public class UserService(IUserRepository repository)
{
    public async Task<UserDto?> GetActiveUserAsync(string id, CancellationToken cancellationToken = default)
    {
        var user = await repository.GetByIdAsync(id, cancellationToken);
        return user switch
        {
            not null when user.Email.EndsWith("@enterprise.com") => user,
            _ => null
        };
    }
}
